                if (!text || text === '$2') return;
                const avatarUrl = 'https://zora404.dpdns.org/file/1787590212370_image.png';
                let moodsHtml = '';
                finalEmotions.forEach((emotion, index) => {
                    const theme = getMoodTheme(emotion);
                    moodsHtml += `<span class="asmod-mood mood-${theme}" style="animation: fadeInAsmod 0.4s ease ${index * 50}ms both;">${emotion}</span>`;
                });
                const html = `
                    <div class="asmod-wrapper">
                        <span class="asmod-corner tl"></span><span class="asmod-corner tr"></span>
                        <div class="asmod-avatar" id="asmod-avatar-container">
                            <div class="avatar-ring"></div>
