                            <div class="asmod-footer"><span class="line"></span>♡ ✦ 欲望低语 ✦ ♡<span class="line r"></span></div>
                        </div>
                    </div>`;
                document.getElementById('main-container').innerHTML = html;
            } catch (error) {
                console.error('[阿丝茉德渲染] 错误:', error);
            }
        }
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', init);
        } else {
            init();
        }
    </script>
